:root {
            --maroon: #5c0f1e;
            --maroon2: #7a1626;
            --gold: #c9a24b;
            --gold-l: #e9cd8a;
            --emerald: #1f5c42;
            --ivory: #fbf3e3;
            --ink: #2c160f;
            --card: #fffdf8;
            --line: rgba(201, 162, 75, .55);
            color-scheme: light;
        }

        @media (prefers-color-scheme:dark) {
            :root:not([data-theme="light"]) {
                --ivory: #160d0a;
                --ink: #f0e2c8;
                --card: #241410;
            }
        }

        :root[data-theme="dark"] {
            --ivory: #160d0a;
            --ink: #f0e2c8;
            --card: #241410;
        }

        * {
            box-sizing: border-box;
            max-width: 100%;
        }

        html {
            overflow-x: hidden;
        }

        html,
        body {
            height: 100%;
            margin: 0;
        }

        body {
            font-family: 'Noto Serif Devanagari', serif;
            background: var(--ivory);
            color: var(--ink);
            overflow-x: hidden;
            padding-top: env(safe-area-inset-top, 0px);
            padding-bottom: env(safe-area-inset-bottom, 0px);
        }

        h1,
        h2,
        h3,
        .en {
            font-family: 'Playfair Display', serif;
        }

        .script {
            font-family: 'Cormorant Garamond', serif;
            font-style: italic;
        }

        .progress {
            position: fixed;
            top: env(safe-area-inset-top, 0px);
            left: 0;
            right: 0;
            height: 4px;
            background: rgba(0, 0, 0, .08);
            z-index: 25;
        }

        .progress>div {
            height: 100%;
            background: linear-gradient(90deg, var(--maroon), var(--gold));
            transition: width .4s;
        }

        #petals {
            position: fixed;
            inset: 0;
            pointer-events: none;
            z-index: 1;
            overflow: hidden;
        }

        .petal {
            position: absolute;
            top: -40px;
            font-size: 20px;
            opacity: .85;
            animation: fall linear infinite;
        }

        @keyframes fall {
            to {
                transform: translateY(112vh) rotate(380deg);
                opacity: 0;
            }
        }

        .spark {
            position: absolute;
            width: 4px;
            height: 4px;
            background: var(--gold-l);
            border-radius: 50%;
            opacity: 0;
            animation: twinkle 2.6s ease-in-out infinite;
        }

        @keyframes twinkle {

            0%,
            100% {
                opacity: 0;
            }

            50% {
                opacity: 1;
            }
        }

        .page {
            display: none;
            min-height: 100svh;
            padding: 56px 18px 44px;
            align-items: center;
            justify-content: center;
            flex-direction: column;
            text-align: center;
            position: relative;
            z-index: 2;
        }

        .page.active {
            display: flex;
            animation: fadeIn .8s ease;
        }

        @keyframes fadeIn {
            from {
                opacity: 0;
                transform: translateY(20px);
            }

            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        .frame {
            position: relative;
            background: var(--card);
            max-width: 580px;
            width: min(94vw, 580px);
            padding: clamp(20px, 5vw, 34px) clamp(16px, 4vw, 24px);
            border-radius: 4px;
            border: 1.5px solid var(--gold);
            box-shadow: 0 14px 40px rgba(0, 0, 0, .25);
        }

        .frame::before,
        .frame::after {
            content: "";
            position: absolute;
            width: 34px;
            height: 34px;
            border: 2px solid var(--gold);
            opacity: .8;
        }

        .frame::before {
            top: -7px;
            left: -7px;
            border-right: none;
            border-bottom: none;
        }

        .frame::after {
            bottom: -7px;
            right: -7px;
            border-left: none;
            border-top: none;
        }

        .divider {
            width: 90px;
            height: 2px;
            margin: 16px auto;
            background: linear-gradient(90deg, transparent, var(--gold), transparent);
        }

        .envelope .frame {
            background: linear-gradient(160deg, var(--maroon), #3d0a14);
            color: var(--gold-l);
            border-color: var(--gold-l);
        }

        .page.hero-bg {
            background: linear-gradient(rgba(20, 5, 10, .55), rgba(20, 5, 10, .72)), url('data:image/png;base64,') center/cover no-repeat;
        }

        .page.hero-bg {
            background-position: 0 0, center 30%;
        }

        .page.hero-bg .frame {
            background: none;
            border: none;
            box-shadow: none;
            color: var(--gold-l);
        }

        .page.hero-bg .frame::before,
        .page.hero-bg .frame::after {
            display: none;
        }

        .page.hero-bg h1,
        .page.hero-bg h2,
        .page.hero-bg .names,
        .page.hero-bg .kicker {
            color: var(--gold-l);
        }

        .page.hero-bg .sub,
        .page.hero-bg .detail {
            color: #fbf3e3;
        }

        .seal {
            width: 62px;
            height: 62px;
            border-radius: 50%;
            background: radial-gradient(circle at 35% 30%, var(--gold-l), var(--gold) 70%);
            margin: 0 auto 14px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-family: 'Playfair Display', serif;
            font-weight: 700;
            color: var(--maroon);
            box-shadow: 0 4px 10px rgba(0, 0, 0, .4);
        }

        .kicker {
            letter-spacing: 3px;
            font-size: .78rem;
            text-transform: uppercase;
            opacity: .85;
        }

        h1 {
            font-size: clamp(1.5rem, 5vw, 2.1rem);
            margin: .2em 0;
        }

        h2 {
            font-size: clamp(1.3rem, 4.5vw, 1.7rem);
            color: var(--maroon);
            margin: .2em 0;
        }

        .names {
            font-size: clamp(1.2rem, 4vw, 1.55rem);
            color: var(--maroon);
            font-weight: 700;
            margin: .3em 0;
        }

        .names.lt {
            color: var(--gold-l);
        }

        .sub {
            font-size: clamp(.95rem, 3vw, 1.1rem);
            line-height: 1.6;
            margin: .7em 0;
            word-wrap: break-word;
        }

        .fun {
            font-style: italic;
            color: var(--emerald);
            margin: .7em 0;
            font-size: 1.02rem;
        }

        .btn {
            display: inline-block;
            background: linear-gradient(90deg, var(--maroon), var(--maroon2));
            color: #fff6e5;
            border: 1px solid var(--gold);
            padding: clamp(10px, 2.5vw, 13px) clamp(18px, 4vw, 26px);
            border-radius: 2px;
            font-family: 'Cormorant Garamond', serif;
            font-size: clamp(.95rem, 3vw, 1.1rem);
            letter-spacing: 1px;
            margin: 8px;
            cursor: pointer;
        }

        .btn.gold {
            background: linear-gradient(90deg, var(--gold), var(--gold-l));
            color: var(--maroon);
            border-color: var(--maroon);
        }

        .btn.wa {
            background: #25D366;
            color: #fff;
            border-color: #1da851;
        }

        .btn:active {
            transform: scale(.97);
        }

        .nav {
            display: flex;
            justify-content: center;
            gap: 10px;
            margin-top: 16px;
            flex-wrap: wrap;
        }

        .detail {
            margin: 5px 0;
            font-size: 1rem;
        }

        .gallery {
            display: flex;
            gap: 8px;
            justify-content: center;
            flex-wrap: wrap;
            margin: 14px 0;
        }

        .ph {
            width: 76px;
            height: 76px;
            border: 1.5px dashed var(--gold);
            border-radius: 4px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10.5px;
            color: var(--maroon);
            background: rgba(201, 162, 75, .08);
        }

        .locgrid {
            display: flex;
            gap: 14px;
            flex-wrap: wrap;
            justify-content: center;
            margin: 14px 0;
        }

        .loccard {
            background: rgba(201, 162, 75, .08);
            border: 1px solid var(--line);
            border-radius: 6px;
            padding: 14px;
            flex: 1;
            min-width: 200px;
        }

        .maplink {
            display: inline-block;
            margin-top: 8px;
            color: var(--maroon);
            text-decoration: underline;
            font-weight: 600;
        }

        .mapbox {
            width: 100%;
            max-width: 520px;
            height: 200px;
            border: 1px solid var(--gold);
            border-radius: 6px;
            margin: 10px auto 4px;
            display: block;
        }

        .loccard .mapbox {
            height: 160px;
        }

        .countdown {
            display: flex;
            gap: 12px;
            justify-content: center;
            margin: 16px 0;
            flex-wrap: wrap;
        }

        .cbox {
            background: var(--maroon);
            color: var(--gold-l);
            border-radius: 6px;
            padding: 10px 14px;
            min-width: 62px;
        }

        .cbox b {
            display: block;
            font-family: 'Playfair Display', serif;
            font-size: 1.4rem;
        }

        .wishbox {
            max-width: 560px;
            width: min(94vw, 560px);
            margin-top: 10px;
            text-align: left;
        }

        .wishbox input,
        .wishbox textarea {
            width: 100%;
            padding: 10px;
            margin: 6px 0;
            border-radius: 4px;
            border: 1px solid var(--gold);
            font-family: inherit;
            background: var(--ivory);
            color: var(--ink);
        }

        .wishlist {
            max-height: 220px;
            overflow-y: auto;
            margin-top: 12px;
            text-align: left;
        }

        .wishitem {
            border-bottom: 1px solid var(--line);
            padding: 8px 0;
        }

        .wishitem b {
            color: var(--maroon);
        }

        .suspense {
            font-size: 1.5rem;
            min-height: 2.4em;
        }

        .toast {
            position: fixed;
            bottom: 24px;
            left: 50%;
            transform: translateX(-50%);
            background: var(--maroon);
            color: #fff6e5;
            padding: 10px 18px;
            border-radius: 20px;
            z-index: 30;
            opacity: 0;
            transition: opacity .4s;
        }

        .toast.show {
            opacity: 1;
        }

        .err {
            color: #b33;
            font-size: .85rem;
        }

        .note {
            font-size: .82rem;
            opacity: .75;
            margin-top: 10px;
        }
